const rawInput = $input.first().json;
// In n8n 2.x, webhook body is in rawInput.body
const input = rawInput.body || rawInput;
const prompt = input.prompt || 'cinematic photograph, dramatic lighting, high quality';
const negative = input.negative_prompt || 'blurry, watermark, text, low quality, deformed';
const width = input.width || 768;
const height = input.height || 512;
const seed = input.seed != null ? input.seed : Math.floor(Math.random() * 999999999);
const steps = input.steps || 25;
const cfg = input.cfg || 7.0;
const model = input.model || 'SD1.5/juggernaut_reborn.safetensors';

const workflow = {
  '4': {class_type: 'CheckpointLoaderSimple', inputs: {ckpt_name: model}},
  '5': {class_type: 'EmptyLatentImage', inputs: {width, height, batch_size: 1}},
  '6': {class_type: 'CLIPTextEncode', inputs: {text: prompt, clip: ['4', 1]}},
  '7': {class_type: 'CLIPTextEncode', inputs: {text: negative, clip: ['4', 1]}},
  '3': {class_type: 'KSampler', inputs: {cfg, denoise: 1.0, latent_image: ['5', 0], model: ['4', 0], negative: ['7', 0], positive: ['6', 0], sampler_name: 'euler_ancestral', scheduler: 'karras', seed, steps}},
  '8': {class_type: 'VAEDecode', inputs: {samples: ['3', 0], vae: ['4', 2]}},
  '9': {class_type: 'SaveImage', inputs: {filename_prefix: 'openm_img', images: ['8', 0]}},
};

return [{json: {workflow: JSON.stringify(workflow), seed, prompt, model}}];

const http = require('http');
const comfyUrl = '172.25.0.1';
const comfyPort = 8188;
const promptId = $input.first().json.prompt_id;
const seed = $('Build Workflow JSON').first()?.json?.seed;
const prompt = $('Build Workflow JSON').first()?.json?.prompt;

if (!promptId) throw new Error('No prompt_id from ComfyUI submit');

function httpGet(path) {
  return new Promise((resolve, reject) => {
    const req = http.get({ hostname: comfyUrl, port: comfyPort, path }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch(e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.setTimeout(10000, () => { req.abort(); reject(new Error('timeout')); });
  });
}

for (let i = 0; i < 600; i++) {
  await new Promise(r => setTimeout(r, 1000));
  const history = await httpGet(`/history/${promptId}`);
  const result = history[promptId];
  if (!result) continue;

  if (result?.status?.status_str === 'error') {
    const msgs = result.status.messages || [];
    const errMsg = msgs.find(m => m[0] === 'execution_error');
    throw new Error(`ComfyUI error: ${JSON.stringify(errMsg || msgs)}`);
  }

  if (result?.status?.completed) {
    for (const nodeOut of Object.values(result.outputs || {})) {
      const files = nodeOut.images || [];
      if (files.length > 0) {
        const f = files[0];
        const qs = `filename=${encodeURIComponent(f.filename)}&subfolder=${encodeURIComponent(f.subfolder||'')}&type=${f.type||'output'}`;
        return [{json: {
          success: true,
          filename: f.filename,
          subfolder: f.subfolder || '',
          type: f.type || 'output',
          download_url: `http://${comfyUrl}:${comfyPort}/view?${qs}`,
          prompt_id: promptId,
          seed,
          prompt
        }}];
      }
    }
    throw new Error('ComfyUI completed but no image output found');
  }
}
throw new Error('Image generation timed out after 10 minutes');
